// Standalone colored-ASCII terminal player: one ES module holding its frames and delay.

export function playerSource(frames, delayMs) {
  return `#!/usr/bin/env node
// Generated by gif2ascii.mjs — standalone colored-ASCII player. Ctrl-C to quit.
const FRAMES = ${JSON.stringify(frames)};
const DELAY_MS = ${delayMs};
const out = process.stdout;
const restore = () => out.write('\\x1b[0m\\x1b[?25h\\x1b[?1049l');
process.on('exit', restore);
process.on('SIGINT', () => process.exit(0));
process.on('SIGTERM', () => process.exit(0));
out.write('\\x1b[?1049h\\x1b[?25l\\x1b[2J');
let i = 0;
setInterval(() => {
  out.write('\\x1b[H' + FRAMES[i]);
  i = (i + 1) % FRAMES.length;
}, DELAY_MS);
`;
}

// Read FRAMES and DELAY_MS back out of a player's source text.
export function parsePlayer(src) {
  const frames = src.match(/^const FRAMES = (.*);$/m);
  const delay = src.match(/^const DELAY_MS = (\d+);$/m);
  if (!frames || !delay) throw new Error('not a gif2ascii player (FRAMES/DELAY_MS not found)');
  return { frames: JSON.parse(frames[1]), delayMs: Number(delay[1]) };
}
